#include <stddef.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>
#include <stdio.h>
#include "openjpeg.h"

typedef struct { const uint8_t* pabyData; size_t nCurPos; size_t nLength; } MemFile;
static void ErrorCallback(const char * msg, void *) { fprintf(stderr, "ERR: %s\n", msg); }
static void WarningCallback(const char * msg, void *) { fprintf(stderr, "WARN: %s\n", msg); }
static void InfoCallback(const char * msg, void *) { fprintf(stderr, "INFO: %s\n", msg); }
static OPJ_SIZE_T ReadCallback(void* pBuffer, OPJ_SIZE_T nBytes, void *pUserData) {
    MemFile* memFile = (MemFile*)pUserData;
    if (memFile->nCurPos >= memFile->nLength) return -1;
    if (memFile->nCurPos + nBytes >= memFile->nLength) {
        size_t nToRead = memFile->nLength - memFile->nCurPos;
        memcpy(pBuffer, memFile->pabyData + memFile->nCurPos, nToRead);
        memFile->nCurPos = memFile->nLength;
        return nToRead;
    }
    if (nBytes == 0) return -1;
    memcpy(pBuffer, memFile->pabyData + memFile->nCurPos, nBytes);
    memFile->nCurPos += nBytes;
    return nBytes;
}
static OPJ_BOOL SeekCallback(OPJ_OFF_T nBytes, void * pUserData) { MemFile* m=(MemFile*)pUserData; m->nCurPos=nBytes; return OPJ_TRUE; }
static OPJ_OFF_T SkipCallback(OPJ_OFF_T nBytes, void * pUserData) { MemFile* m=(MemFile*)pUserData; m->nCurPos+=nBytes; return nBytes; }

int main(int argc, char* argv[]) {
    FILE* f = fopen(argv[1], "rb");
    fseek(f, 0, SEEK_END); long nLen = ftell(f); fseek(f, 0, SEEK_SET);
    uint8_t* buf = (uint8_t*)malloc(nLen);
    fread(buf, nLen, 1, f); fclose(f);

    opj_codec_t* pCodec = opj_create_decompress(OPJ_CODEC_J2K);
    opj_set_info_handler(pCodec, InfoCallback, NULL);
    opj_set_warning_handler(pCodec, WarningCallback, NULL);
    opj_set_error_handler(pCodec, ErrorCallback, NULL);
    opj_dparameters_t parameters;
    opj_set_default_decoder_parameters(&parameters);
    opj_setup_decoder(pCodec, &parameters);
    opj_stream_t *pStream = opj_stream_create(1024, OPJ_TRUE);
    MemFile memFile; memFile.pabyData=buf; memFile.nLength=nLen; memFile.nCurPos=0;
    opj_stream_set_user_data_length(pStream, nLen);
    opj_stream_set_read_function(pStream, ReadCallback);
    opj_stream_set_seek_function(pStream, SeekCallback);
    opj_stream_set_skip_function(pStream, SkipCallback);
    opj_stream_set_user_data(pStream, &memFile, NULL);
    opj_image_t * psImage = NULL;
    fprintf(stderr, "=== read_header ===\n");
    if (!opj_read_header(pStream, pCodec, &psImage)) { fprintf(stderr, "read_header FAILED\n"); return 0; }
    fprintf(stderr, "read_header OK, image %ux%u\n", psImage->x1-psImage->x0, psImage->y1-psImage->y0);
    OPJ_UINT32 width = psImage->x1 - psImage->x0;
    OPJ_UINT32 height = psImage->y1 - psImage->y0;
    OPJ_UINT32 width_to_read = width>1024?1024:width;
    OPJ_UINT32 height_to_read = height>1024?1024:height;
    fprintf(stderr, "=== set_decode_area ===\n");
    if (opj_set_decode_area(pCodec, psImage, psImage->x0, psImage->y0, psImage->x0+width_to_read, psImage->y0+height_to_read)) {
        fprintf(stderr, "=== decode ===\n");
        if (opj_decode(pCodec, pStream, psImage)) { fprintf(stderr, "decode OK\n"); }
        else fprintf(stderr, "decode FAILED\n");
    } else fprintf(stderr, "set_decode_area FAILED\n");
    fprintf(stderr, "=== end_decompress ===\n");
    opj_end_decompress(pCodec, pStream);
    return 0;
}
EOF
